SELECT ?uri ?label ?ts WHERE {
  ?p brick:hasPoint ?uri .
  ?uri ref:hasTimeseriesId ?ts
  OPTIONAL { ?uri rdfs:label ?label }
  FILTER (regex(str(?uri), "CHWP01|CondPump02|SupplyFan_AHU01", "i"))
} LIMIT 100

SELECT ?p ?label ?ts WHERE {
  ?p rdfs:label ?label .
  ?p ref:hasTimeseriesId ?ts
  FILTER (regex(str(?label), "CHWPump01|CondPump02|SupplyFan_AHU01", "i"))
} LIMIT 50

SELECT ?e ?ename ?p ?pcls ?ts WHERE {
  ?e ref:ifcName ?ename .
  ?p brick:isPointOf ?e .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER (regex(str(?ename), "CHWPump01|CondPump02|SupplyFan_AHU01"))
} LIMIT 100

SELECT ?e ?ename ?p ?pcls ?ts WHERE {
  ?e ref:ifcName ?ename .
  ?p brick:isPointOf ?e .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER (regex(str(?ename), "pump|Pump|CHWP|CondPump", "i"))
} LIMIT 100

SELECT ?e ?ename ?p ?pcls ?ts WHERE {
  ?e ref:ifcName ?ename .
  ?p brick:isPointOf ?e .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER (regex(str(?ename), "fan|Fan", "i"))
} LIMIT 100

SELECT ?ename ?p ?pcls ?ts ?unit WHERE {
  ?e ref:ifcName ?ename .
  ?p brick:isPointOf ?e .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  OPTIONAL { ?p qudt:hasUnit ?unit }
  FILTER (?ename IN ("CHWPump01","CondPump02","SupplyFan_AHU01"))
} LIMIT 100

SELECT ?ename ?p ?pcls ?ts ?unit WHERE {
  ?e ref:ifcName ?ename .
  ?p brick:isPointOf ?e .
  FILTER (?ename IN ("CHWPump01","CondPump02","SupplyFan_AHU01"))
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 100

SELECT ?p ?pcls ?ts ?label WHERE {
  ?p brick:isPointOf [ ref:ifcName "SupplyFan_AHU01" ] .
  OPTIONAL { ?p qudt:hasUnit ?pcls }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  OPTIONAL { ?p rdfs:label ?label }
} LIMIT 100

SELECT ?p ?ts WHERE {
  ?p https://brickschema.org/schema/Brick#isPointOf ?e .
  ?e ref:ifcName ?en .
  FILTER (?en = "SupplyFan_AHU01")
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 100

SELECT ?p ?ts WHERE {
  ?p a brick:Point .
  ?p brick:isPointOf ?e .
  ?e ref:ifcName ?en .
  FILTER (?en = "SupplyFan_AHU01")
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 100

